import axios from "axios"

class NetAxios {
    constructor() {
        this.baseURL = "https://potato.u282401.nyat.app:25637/authcore"
        this.timeout = 30000
    }

    async request(options) {
        const instance = axios.create()
        
        let config = {
            ...options,
            baseURL: this.baseURL,
            timeout: this.timeout
        }
        return instance(config)
    }

}

export default new NetAxios()