  mounted() {
    this.getJbKeys()
  },
  methods: {
    copyValue(type, index, event) {

      let item = this.jbKeys[index]
      if (type == 'plugin') {
        item = this.plugins[index]
      }

      
      let version = Object.keys(item)[0]
      let val = item[version]
      
      const button = event.currentTarget;

      let input = document.createElement("input")
      input.type = "text"
      input.value = val
      document.body.appendChild(input)



      try {
        input.select()
        document.execCommand("copy")
        button.innerText = 'Copied!'
      } catch (error) {
        button.innerText = "Copy failed"
      }

      document.body.removeChild(input)

      setTimeout(() => {
        button.innerText = "Copy to clipboard"
      }, 1500)

    },
    getJbKeys() {
      GetJbKeys().then(result => {
        let data = result.data
        let jbKeys = data.jbKeys
        let plugins = {}
        let softwares = {}

        for (let index in jbKeys) {
          if (index.toLowerCase() in this.icons) {
            softwares[index] = jbKeys[index]
          } else {
            plugins[index] = jbKeys[index]
          }
        }

        this.jbKeys = softwares
        this.plugins = plugins

        let jetbraName = data.jetbraName

        let downloadUrl = "https://potato.u282401.nyat.app:44806/authcore/files/" + jetbraName;

        this.$message({
          dangerouslyUseHTMLString: true,
          message: '🇷🇺 Download <a target="_blank" href="' + downloadUrl + '">jetbra.zip</a> (251031), and configure as described in readme.txt! For testing purposes only, not for commercial use! '
                  + '<br/><br/>'
                  + '<b>🇷🇺 Please note that this is just a personal page, not an official website!</b>',
          duration: 0,
          customClass: 'default-message',
          iconClass: 'icon-defined'
        })

      }).catch(err => {
        this.$message.error(err)
      })
    }
  }
}
